const response = $input.item.json.response || $input.item.json.content;

// Extract JSON metadata from response
const jsonMatch = response.match(/```json\s*([\s\S]*?)\s*```/);

if (!jsonMatch) {
  throw new Error('No JSON metadata found in Claude response');
}

const metadata = JSON.parse(jsonMatch[1]);

// Extract article content (everything before JSON block)
let articleContent = response.split('```json')[0].trim();

// If article_markdown is in metadata, use that instead
if (metadata.article_markdown) {
  articleContent = metadata.article_markdown;
}

// Generate slug if not provided
if (!metadata.slug) {
  metadata.slug = metadata.title
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .substring(0, 100);
}

// Calculate reading time if not provided
if (!metadata.reading_time) {
  const wordCount = articleContent.split(/\s+/).length;
  metadata.reading_time = Math.ceil(wordCount / 200);
}

return {
  json: {
    ...metadata,
    content: articleContent,
    original_queue_id: $('Get Queue Item').item.json.id,
    original_url: $('Get Queue Item').item.json.original_url,
    source: $('Get Queue Item').item.json.source,
    source_published_date: $('Get Queue Item').item.json.source_published_date
  }
};

const images = $input.item.json.results || [];
const previousData = $('Parse Claude Response').item.json;

let featuredImageUrl = null;
let imageCredit = null;

if (images.length > 0) {
  const selectedImage = images[0];
  featuredImageUrl = selectedImage.urls.regular;
  imageCredit = {
    photographer: selectedImage.user.name,
    photographer_url: selectedImage.user.links.html,
    source: 'Unsplash'
  };
}

return {
  json: {
    ...previousData,
    featured_image_url: featuredImageUrl,
    image_credit: imageCredit
  }
};
